@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-tree-view-width, 20rem);
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
  }

  .tree,
  .branch,
  .branchContent {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
  }

  .tree {
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .branchControl,
  .item {
    /* Nesting offset for the content and highlight; Ark sets --depth on the branch and item. */
    --_tree-view-indent: calc(
      (var(--depth) - 1) * var(--moduix-tree-view-indent, var(--moduix-spacing-4))
    );

    position: relative;
    z-index: 0;
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    min-height: var(--moduix-size-sm);
    align-items: center;
    gap: var(--moduix-spacing-2);
    border-radius: var(--moduix-radius-sm);
    outline: none;
    padding-block: var(--moduix-spacing-1);
    padding-inline: calc(var(--_tree-view-indent) + var(--moduix-spacing-2)) var(--moduix-spacing-2);
    color: inherit;
    cursor: pointer;
    font: inherit;
    text-align: start;
    text-decoration: none;
    transition:
      color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);
    user-select: none;

    &::before {
      position: absolute;
      z-index: -1;
      inset-block: 0;
      /* Starts past the parent's indent guide, leaving room before the indicator. */
      inset-inline: calc(var(--_tree-view-indent) + var(--moduix-spacing-1)) 0;
      border-radius: inherit;
      content: '';
      box-shadow: inset 0 0 0 var(--moduix-focus-ring-inset-width) transparent;
      pointer-events: none;
      transition:
        background-color var(--moduix-transition-default),
        box-shadow var(--moduix-transition-default);
    }

    @media (hover: hover) {
      &:not([data-disabled]):hover {
        color: var(--moduix-color-accent-foreground);

        &::before {
          background-color: var(--moduix-color-accent);
        }
      }
    }

    &:focus-visible::before,
    &[data-focus]::before {
      box-shadow: inset 0 0 0 var(--moduix-focus-ring-inset-width) var(--moduix-color-ring);
    }

    &[data-selected] {
      color: var(--moduix-color-accent-foreground);

      &::before {
        background-color: var(--moduix-color-accent);
      }
    }

    &[data-disabled] {
      cursor: default;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .item {
    padding-inline-start: calc(var(--_tree-view-indent) + var(--moduix-spacing-4));
  }

  .branchTrigger,
  .branchIndicator,
  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & svg {
      width: var(--moduix-spacing-3-5);
      height: var(--moduix-spacing-3-5);
    }
  }

  .branchTrigger,
  .branchIndicator {
    transition: transform var(--moduix-transition-default);

    &[data-state='open'] {
      transform: rotate(90deg);
    }
  }

  /* Block, not flex: text-overflow only truncates text in a block container. */
  .branchText,
  .itemText {
    min-width: 0;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    /* Centered on the line box; `middle` aligns to the x-height and sits low. */
    & svg {
      display: inline-block;
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      margin-block: calc((1lh - var(--moduix-spacing-4)) / 2);
      margin-inline-end: var(--moduix-spacing-2);
      vertical-align: top;
    }
  }

  .branchContent {
    position: relative;
    overflow: hidden;

    &[data-state='open'] {
      animation: global(moduix-collapsible-content-open) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-collapsible-content-closed) var(--moduix-transition-default);
    }

    @media (prefers-reduced-motion: reduce) {
      &[data-state] {
        animation: none;
      }
    }
  }

  /* Centered under the branch indicator; inherits --depth from the branch. */
  .branchIndentGuide {
    position: absolute;
    z-index: 1;
    inset-block: 0;
    inset-inline-start: calc(
      (var(--depth) - 1) * var(--moduix-tree-view-indent, var(--moduix-spacing-4)) +
        var(--moduix-spacing-4)
    );
    width: var(--moduix-border-width-sm);
    background-color: var(--moduix-color-border);
    pointer-events: none;
  }

  .nodeCheckbox {
    box-sizing: border-box;
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-xs);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-primary-foreground);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-border-width-sm);
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-state='checked'],
    &[data-state='indeterminate'] {
      border-color: var(--moduix-color-primary);
      background-color: var(--moduix-color-primary);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &[data-disabled] {
      cursor: default;
      opacity: var(--moduix-opacity-disabled);
    }

    /* The disabled row already dims the checkbox. */
    :is(.item, .branchControl)[data-disabled] & {
      opacity: 1;
    }

    & svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }
  }

  .nodeCheckboxIndicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .nodeRenameInput {
    box-sizing: border-box;
    min-width: 0;
    flex: 1;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-ring);
    border-radius: var(--moduix-radius-xs);
    padding-block: 0;
    padding-inline: var(--moduix-spacing-1);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: calc(var(--moduix-focus-ring-inset-width) * -1);

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }
  }
}
